/** Shape returned by the Mailboxlayer /check endpoint on success. */
export type MailboxlayerResponse = {
  email: string;
  did_you_mean: string;
  user: string;
  domain: string;
  format_valid: boolean;
  mx_found: boolean | null;
  smtp_check: boolean | null;
  catch_all: boolean | null;
  role: boolean;
  disposable: boolean;
  free: boolean;
  score: number;
};

/** Error envelope Mailboxlayer returns instead of a result (HTTP 200 with success:false). */
export type MailboxlayerError = {
  success: false;
  error: { code: number; type: string; info: string };
};

/** One row of the results table: either a verification result or a per-email failure. */
export type VerifyRow =
  | { email: string; ok: true; data: MailboxlayerResponse; elapsedMs: number }
  | { email: string; ok: false; error: string };

export type VerifyResponse = {
  rows: VerifyRow[];
  /** Emails dropped before hitting the API because they were duplicates. */
  duplicates: number;
  /** Emails dropped because the batch exceeded MAX_BATCH. */
  truncated: number;
  elapsedMs: number;
};

/** Hard ceiling per request — each email costs one Mailboxlayer credit. */
export const MAX_BATCH = 100;

/**
 * Pull email-looking tokens out of free text or raw CSV.
 *
 * Deliberately permissive: we split on the usual separators and keep anything
 * containing an "@", so malformed addresses still reach the API and come back
 * with format_valid: false rather than being silently dropped here.
 */
export function extractEmails(input: string): string[] {
  return input
    .split(/[\s,;]+/)
    .map((token) => token.replace(/^["'<(]+|["'>)]+$/g, "").trim())
    .filter((token) => token.includes("@"));
}

/** Case-insensitive de-dupe that preserves first-seen order and original casing. */
export function dedupe(emails: string[]): { unique: string[]; duplicates: number } {
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const email of emails) {
    const key = email.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(email);
  }
  return { unique, duplicates: emails.length - unique.length };
}

/** Buckets the 0–1 score into the labels used by the table and summary bar. */
export function scoreBand(score: number): "high" | "medium" | "low" {
  if (score >= 0.65) return "high";
  if (score >= 0.4) return "medium";
  return "low";
}

/**
 * Overall verdict for a row — what most people actually want out of the table.
 * SMTP is authoritative when present; otherwise we fall back to syntax + MX.
 */
export function verdict(data: MailboxlayerResponse): "deliverable" | "risky" | "undeliverable" {
  if (!data.format_valid || data.mx_found === false) return "undeliverable";
  if (data.smtp_check === false) return "undeliverable";
  if (data.disposable || data.catch_all || data.score < 0.4) return "risky";
  return "deliverable";
}

"use client";

import { useRef, useState } from "react";
import { MAX_BATCH, extractEmails } from "@/app/lib/mailbox";

const SAMPLES = [
  { label: "role", email: "support@apilayer.com" },
  { label: "free", email: "someone@gmail.com" },
  { label: "disposable", email: "test@mailinator.com" },
  { label: "typo", email: "hello@gmial.com" },
];

export function VerifyPanel({
  onVerify,
  loading,
}: {
  onVerify: (emails: string[]) => void;
  loading: boolean;
}) {
  const [value, setValue] = useState("");
  const [fileName, setFileName] = useState<string | null>(null);
  const [dragging, setDragging] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null);

  const parsed = extractEmails(value);

  async function ingestFile(file: File) {
    const text = await file.text();
    const found = extractEmails(text);
    setFileName(`${file.name} · ${found.length} found`);
    setValue(found.join(", "));
  }

  function submit(e: React.FormEvent) {
    e.preventDefault();
    if (parsed.length > 0) onVerify(parsed);
  }

  return (
    <section className="rounded-xl border border-border bg-bg-elev">
      <div className="flex items-center gap-2 border-b border-border px-5 py-3">
        <span className="mono text-[10px] uppercase tracking-wider text-fg-dim">
          verify
        </span>
        <span className="mono text-xs text-fg-muted">
          one email, a comma-separated list, or a CSV
        </span>
      </div>

      <form onSubmit={submit} className="flex flex-col gap-3 p-5">
        <textarea
          value={value}
          onChange={(e) => setValue(e.target.value)}
          placeholder="jane@example.com, support@apilayer.com, test@mailinator.com"
          rows={4}
          spellCheck={false}
          autoComplete="off"
          className="scrollbar-thin mono min-h-24 w-full resize-y rounded-md border border-border bg-bg px-3 py-2 text-sm text-fg placeholder:text-fg-dim focus:border-accent focus:outline-none"
        />

        <div
          onDragOver={(e) => {
            e.preventDefault();
            setDragging(true);
          }}
          onDragLeave={() => setDragging(false)}
          onDrop={(e) => {
            e.preventDefault();
            setDragging(false);
            const file = e.dataTransfer.files?.[0];
            if (file) void ingestFile(file);
          }}
          className={`flex items-center justify-between gap-3 rounded-md border border-dashed px-4 py-3 transition ${
            dragging ? "border-accent bg-accent/5" : "border-border bg-bg-elev-2"
          }`}
        >
          <span className="mono truncate text-xs text-fg-muted">
            {fileName ?? "drop a .csv or .txt here"}
          </span>
          <button
            type="button"
            onClick={() => fileInput.current?.click()}
            className="mono shrink-0 rounded border border-border bg-bg-elev px-2 py-1 text-[11px] text-fg-muted transition hover:text-fg"
          >
            browse
          </button>
          <input
            ref={fileInput}
            type="file"
            accept=".csv,.txt,text/csv,text/plain"
            className="hidden"
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) void ingestFile(file);
              e.target.value = "";
            }}
          />
        </div>

        <div className="flex flex-wrap items-center gap-2">
          <span className="mono text-[10px] uppercase tracking-wider text-fg-dim">
            samples
          </span>
          {SAMPLES.map((s) => (
            <button
              key={s.email}
              type="button"
              disabled={loading}
              onClick={() =>
                setValue((v) => (v.trim() ? `${v.trim()}, ${s.email}` : s.email))
              }
              className="mono rounded border border-border bg-bg-elev-2 px-2 py-1 text-[11px] text-fg-muted transition hover:text-fg disabled:opacity-50"
            >
              {s.label} · {s.email}
            </button>
          ))}
        </div>

        <div className="flex items-center justify-between gap-3 border-t border-border pt-3">
          <span className="mono text-[11px] text-fg-dim">
            {parsed.length === 0
              ? "no addresses detected"
              : `${parsed.length} address${parsed.length === 1 ? "" : "es"} detected`}
            {parsed.length > MAX_BATCH && ` · only the first ${MAX_BATCH} will run`}
          </span>
          <div className="flex gap-2">
            <button
              type="button"
              disabled={loading || value === ""}
              onClick={() => {
                setValue("");
                setFileName(null);
              }}
              className="mono h-10 rounded-md border border-border bg-bg-elev-2 px-3 text-sm text-fg-muted transition hover:text-fg disabled:opacity-50"
            >
              clear
            </button>
            <button
              type="submit"
              disabled={loading || parsed.length === 0}
              className="mono h-10 rounded-md border border-accent/40 bg-accent/15 px-4 text-sm font-medium text-accent transition hover:bg-accent/25 disabled:opacity-50"
            >
              {loading ? "verifying…" : "verify"}
            </button>
          </div>
        </div>
      </form>
    </section>
  );
}

"use client";

import { useSyncExternalStore } from "react";

type Theme = "dark" | "light";
const KEY = "mailwiz-theme";

/**
 * `data-theme` on <html> is the source of truth — the inline script in layout.tsx
 * sets it before paint, so we read it as an external store rather than mirroring
 * it into state. The server snapshot matches that script's default.
 */
function subscribe(onChange: () => void) {
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["data-theme"],
  });
  return () => observer.disconnect();
}

const getSnapshot = (): Theme =>
  document.documentElement.dataset.theme === "light" ? "light" : "dark";

export function ThemeToggle() {
  const theme = useSyncExternalStore(subscribe, getSnapshot, () => null);
  const mounted = theme !== null;

  function toggle() {
    const next: Theme = theme === "dark" ? "light" : "dark";
    document.documentElement.dataset.theme = next;
    try {
      localStorage.setItem(KEY, next);
    } catch {}
  }

  const isDark = theme !== "light";

  return (
    <button
      type="button"
      onClick={toggle}
      aria-label={`Switch to ${isDark ? "light" : "dark"} mode`}
      className="mono flex h-7 items-center gap-1.5 rounded-md border border-border bg-bg-elev-2 px-2 text-[11px] text-fg-muted transition hover:text-fg"
      suppressHydrationWarning
    >
      {mounted ? (
        <>
          <span aria-hidden>{isDark ? <MoonIcon /> : <SunIcon />}</span>
          <span className="hidden sm:inline">{isDark ? "dark" : "light"}</span>
        </>
      ) : (
        <span className="inline-block h-3 w-3" />
      )}
    </button>
  );
}

function SunIcon() {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      className="h-3 w-3"
      aria-hidden
    >
      <circle cx="12" cy="12" r="4" />
      <path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41" />
    </svg>
  );
}

function MoonIcon() {
