import { BASE_PATH } from "./basePath";

/**
 * Resolves a `public/` asset path for rendering.
 *
 * next.config.ts sets `images: { unoptimized: true }`, which bypasses
 * next/image's loader — and with it, the loader's automatic basePath
 * prefixing. Left alone, `<Image src="/logo.png">` renders a plain
 * `<img src="/logo.png">` that resolves against the domain root instead of
 * this app's basePath, 404ing once deployed under /devtools/verify-email.
 * This helper prepends BASE_PATH itself so every asset resolves correctly
 * regardless of that loader behavior.
 *
 * Setting NEXT_PUBLIC_ASSET_BASE_URL (e.g. to a CDN) switches every call
 * site to an absolute URL instead, bypassing basePath entirely.
 */
const ASSET_BASE_URL = process.env.NEXT_PUBLIC_ASSET_BASE_URL?.replace(/\/+$/, "");

export function assetPath(path: string): string {
  if (!path.startsWith("/")) {
    throw new Error(`assetPath() expects a path starting with "/", received: "${path}"`);
  }
  return ASSET_BASE_URL ? `${ASSET_BASE_URL}${path}` : `${BASE_PATH}${path}`;
}

"use client";

import { useState } from "react";
import { VerifyPanel } from "./VerifyPanel";
import { ResultsTable } from "./ResultsTable";
import { PromoBanner } from "./PromoBanner";
import type { VerifyResponse } from "@/app/lib/mailbox";

export function Verifier() {
  const [result, setResult] = useState<VerifyResponse | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  async function verify(emails: string[]) {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch("/api/verify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ emails }),
      });
      const body = await res.json();
      if (!res.ok) {
        setError(body.error ?? `Request failed with ${res.status}`);
        setResult(null);
      } else {
        setResult(body as VerifyResponse);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setResult(null);
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="grid-bg flex-1">
      <div className="mx-auto flex max-w-6xl flex-col gap-5 px-6 py-10">
        <div className="flex flex-col gap-2">
          <h1 className="text-2xl font-semibold tracking-tight text-fg sm:text-3xl">
            Separate real inboxes from the rest.
          </h1>
          <p className="max-w-2xl text-sm text-fg-muted">
            Syntax, MX records, live SMTP ping, catch-all detection, role and
            disposable filtering, plus a deliverability score — for one address
            or a whole CSV. Powered by the Mailboxlayer API.
          </p>
        </div>

        <VerifyPanel onVerify={verify} loading={loading} />

        <PromoBanner />

        {error && (
          <div className="mono rounded-xl border border-danger/40 bg-danger/10 px-5 py-3 text-sm text-danger">
            {error}
          </div>
        )}

        {loading && !result && (
          <div className="mono rounded-xl border border-border bg-bg-elev px-5 py-8 text-center text-sm text-fg-dim">
            pinging mail servers…
          </div>
        )}

        {result && <ResultsTable result={result} />}
      </div>
    </main>
  );
}
